import React, { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import { AlertTriangle, Bell, CalendarDays, Check, ChevronRight, Compass as HeartPulse, LayoutDashboard, LogOut, MessageCircle, Pill, Plus, Send, Settings, ShieldCheck, UserPlus, UsersRound, X } from "lucide-react";
import "./styles.css";
import "./readability.css";

const API=import.meta.env.VITE_API_URL||(import.meta.env.DEV?"http://localhost:5000/api":"/api");
const formatDate=value=>new Intl.DateTimeFormat("ru-RU",{day:"numeric",month:"long"}).format(new Date(value));
const authFetch=(path,token,options={})=>fetch(`${API}${path}`,{...options,headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`,...options.headers}});

function Auth({onAuth}){
  const[mode,setMode]=useState("login");const[form,setForm]=useState({name:"",email:"",password:"",specialty:"Психиатр",experience:0,clinic:"Частная практика"});const[error,setError]=useState("");const[busy,setBusy]=useState(false);
  const submit=async e=>{e.preventDefault();setBusy(true);setError("");const path=mode==="login"?"/auth/login":"/auth/register";const body=mode==="login"?{email:form.email,password:form.password}:{...form,role:"doctor"};const r=await fetch(`${API}${path}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const result=await r.json();setBusy(false);if(!r.ok)return setError(result.error);onAuth(result.token,result.user)};
  return <div className="auth-screen"><div className="auth-brand"><span><HeartPulse/></span><strong>Клинический компас</strong><small>кабинет врача</small></div><form className="auth-card" onSubmit={submit}><span className="kicker">Начало работы</span><h1>{mode==="login"?"Вход для врача":"Регистрация врача"}</h1><p>{mode==="login"?"Введите данные своей учётной записи.":"Создайте профиль. Стоимость приёма можно указать позже в личном кабинете."}</p>{mode==="register"&&<><label>ФИО<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Алексей Волков"/></label><div className="form-row"><label>Специализация<input value={form.specialty} onChange={e=>setForm({...form,specialty:e.target.value})}/></label><label>Опыт, лет<input type="number" min="0" value={form.experience} onChange={e=>setForm({...form,experience:Number(e.target.value)})}/></label></div><label>Клиника<input value={form.clinic} onChange={e=>setForm({...form,clinic:e.target.value})}/></label></>}<label>Email<input type="email" required value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="doctor@example.ru"/></label><label>Пароль<input type="password" minLength="6" required value={form.password} onChange={e=>setForm({...form,password:e.target.value})} placeholder="Минимум 6 символов"/></label>{error&&<div className="form-error">{error}</div>}<button className="auth-submit" disabled={busy}>{busy?"Подождите…":mode==="login"?"Войти":"Создать профиль"}</button><button type="button" className="auth-switch" onClick={()=>{setMode(mode==="login"?"register":"login");setError("")}}>{mode==="login"?"Я новый врач — зарегистрироваться":"Уже есть профиль — войти"}</button></form></div>
}

function App(){
 const[token,setToken]=useState(localStorage.getItem("doctorToken")||"");const[user,setUser]=useState(null);const[data,setData]=useState(null);const[tab,setTab]=useState("overview");const[schedule,setSchedule]=useState([]);const[notices,setNotices]=useState([]);const[noticeOpen,setNoticeOpen]=useState(false);const[signalsOpen,setSignalsOpen]=useState(false);const[patientToOpen,setPatientToOpen]=useState(null);const[appointmentPatient,setAppointmentPatient]=useState(null);const[toast,setToast]=useState("");const[error,setError]=useState("");
 const flash=t=>{setToast(t);setTimeout(()=>setToast(""),2500)};
 const load=async current=>{const active=current||token;if(!active)return;try{const me=await authFetch("/auth/me",active);if(me.status===401)throw new Error("auth");const meData=await me.json();const[dash,notes]=await Promise.all([authFetch("/doctor/dashboard",active),authFetch("/notifications",active)]);const dashboard=await dash.json();setUser(meData);setData(dashboard);setNotices(await notes.json());const slots=await authFetch(`/schedule/doctor/${meData.entity_id}`,active);setSchedule((await slots.json()).days);setError("");}catch(e){if(e.message==="auth"){localStorage.removeItem("doctorToken");setToken("");setUser(null)}else setError("Не удалось загрузить кабинет")}};
 useEffect(()=>{
   load();
   if(!token)return;
   const sync=()=>{if(document.visibilityState==="visible")load()};
   const timer=setInterval(sync,1500);
   window.addEventListener("focus",sync);
   document.addEventListener("visibilitychange",sync);
   return()=>{clearInterval(timer);window.removeEventListener("focus",sync);document.removeEventListener("visibilitychange",sync)};
 },[token]);
 const onAuth=(value,profile)=>{localStorage.setItem("doctorToken",value);setToken(value);setUser(profile)};
 const logout=async()=>{await authFetch("/auth/logout",token,{method:"POST"});localStorage.removeItem("doctorToken");setToken("");setUser(null);setData(null)};
 const openNotices=async()=>{setNoticeOpen(!noticeOpen);const unread=notices.filter(i=>!i.read).map(i=>i.key);if(unread.length){await authFetch("/notifications/read",token,{method:"POST",body:JSON.stringify({keys:unread})});setNotices(notices.map(i=>({...i,read:true})))}};
 if(!token)return <Auth onAuth={onAuth}/>;if(!data)return <div className="state"><div className="loader"/><p>{error||"Загружаем кабинет…"}</p></div>;
 const nav=[["overview",LayoutDashboard,"Обзор"],["patients",UsersRound,"Пациенты"],["schedule",CalendarDays,"Расписание"],["chat",MessageCircle,"Чат"],["medicines",Pill,"Препараты"],["profile",Settings,data.doctor.is_chief?"Профиль и клиника":"Мой профиль"]];const unread=notices.filter(i=>!i.read).length;
 const openPatient=id=>{setPatientToOpen(id);setSignalsOpen(false);setTab("patients")};
 return <div className="shell"><aside><div className="brand"><span><HeartPulse/></span><div><strong>Клинический</strong><small>компас · врач</small></div></div><nav>{nav.map(([id,Icon,label])=><button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}><Icon/>{label}{id==="overview"&&data.metrics.need_attention>0&&<i>{data.metrics.need_attention}</i>}</button>)}</nav><div className="privacy"><ShieldCheck/><div><strong>Защищённый контур</strong><p>Медицинские данные зашифрованы</p></div></div><div className="doctor-mini"><span>{initials(data.doctor.name)}</span><div><strong>{data.doctor.name}</strong><small>{data.doctor.specialty}</small></div><button onClick={logout} title="Выйти"><LogOut/></button></div></aside><main><header><span className="crumb">Кабинет врача <ChevronRight/> {nav.find(i=>i[0]===tab)?.[2]}</span><div className="header-actions"><button className="bell" onClick={openNotices}><Bell/>{unread>0&&<i/>}</button>{noticeOpen&&<Notifications items={notices} close={()=>setNoticeOpen(false)}/>}</div></header><div className="page">{tab==="overview"&&<Overview data={data} go={setTab} openPatient={openPatient} openSignals={()=>setSignalsOpen(true)}/>} {tab==="patients"&&<Patients token={token} patients={data.patients} initialPatientId={patientToOpen} goChat={()=>setTab("chat")} addAppointment={setAppointmentPatient} refresh={load} flash={flash}/>} {tab==="schedule"&&<Schedule token={token} days={schedule} refresh={load} flash={flash}/>} {tab==="chat"&&<Chat token={token} patients={data.patients} close={()=>setTab("overview")}/>} {tab==="medicines"&&<Medicines/>} {tab==="profile"&&<DoctorProfile token={token} doctor={data.doctor} refresh={load} flash={flash}/>}</div></main>{signalsOpen&&<AttentionModal token={token} alerts={data.alerts} close={()=>setSignalsOpen(false)} openPatient={openPatient} refresh={load} flash={flash}/>} {appointmentPatient&&<AppointmentModal token={token} doctor={data.doctor} patient={appointmentPatient} schedule={schedule} close={()=>setAppointmentPatient(null)} done={()=>{setAppointmentPatient(null);flash("Приём создан и отправлен пациенту на подтверждение");load()}}/>}{toast&&<div className="toast"><Check/>{toast}</div>}</div>
}

const initials=name=>name.split(" ").map(i=>i[0]).slice(0,2).join("");
function Title({kicker,title,text,action}){return <div className="page-title"><div><span className="kicker">{kicker}</span><h1>{title}</h1><p>{text}</p></div>{action}</div>}
function Empty({icon:Icon,title,text,action,label}){return <div className="empty-big"><span><Icon/></span><h2>{title}</h2><p>{text}</p>{action&&<button className="primary" onClick={action}>{label}</button>}</div>}
function Notifications({items,close}){return <div className="notice-pop"><div><strong>Уведомления</strong><button onClick={close}><X/></button></div>{items.length?items.map(i=><article className={i.read?"read":""} key={i.key}><span/><section><strong>{i.title}</strong><p>{i.text}</p><small>{formatDate(i.created_at)}</small></section></article>):<p className="notice-empty">Новых событий пока нет</p>}</div>}

function Overview({data,go,openPatient,openSignals}){return <><Title kicker="Рабочее пространство" title={`Здравствуйте, ${data.doctor.name.split(" ")[0]}`} text="Данные обновляются автоматически. Новый приём назначается из карточки пациента."/><div className="metrics"><button type="button" className="metric rose" onClick={()=>go("patients")}><span><UsersRound/></span><div><small>Пациенты</small><strong>{data.metrics.patients}</strong><p>открыть список</p></div></button><button type="button" className="metric red" onClick={openSignals}><span><AlertTriangle/></span><div><small>Требуют внимания</small><strong>{data.metrics.need_attention}</strong><p>открыть сигналы</p></div><ChevronRight className="metric-arrow"/></button><button type="button" className="metric plum" onClick={()=>go("schedule")}><span><CalendarDays/></span><div><small>Предстоящие</small><strong>{data.metrics.appointments}</strong><p>открыть расписание</p></div></button></div>{!data.patients.length?<Empty icon={UserPlus} title="Пациентов пока нет" text="Пациент появится здесь после первой самостоятельной записи к вам."/>:<div className="grid two">{data.patients.map(p=><section className="panel" key={p.patient_id}><div className="panel-head"><div><span className="kicker">Пациент</span><h2>{p.full_name}</h2></div><span className="tag">Под наблюдением</span></div><p><strong>Диагнозы:</strong> {p.diagnoses?.length?p.diagnoses.map(item=>item.name).join(", "):"пока не установлены"}</p><div className="patient-actions"><button className="wide" onClick={()=>openPatient(p.patient_id)}>Открыть карточку</button><button className="wide" onClick={()=>go("chat")}><MessageCircle/>Чат</button></div></section>)}</div>}</>}

function AttentionModal({token,alerts,close,openPatient,refresh,flash}){
 const[notes,setNotes]=useState({}),[errors,setErrors]=useState({});
 const acknowledge=async id=>{const response=await authFetch(`/doctor/alerts/${id}/acknowledge`,token,{method:"POST"});if(response.ok){flash("Сигнал принят в работу");await refresh()}};
 const resolve=async id=>{const note=(notes[id]||"").trim();if(!note)return setErrors({...errors,[id]:"Коротко укажите результат действий"});const response=await authFetch(`/doctor/alerts/${id}/resolve`,token,{method:"POST",body:JSON.stringify({note})});const value=await response.json();if(!response.ok)return setErrors({...errors,[id]:value.error});flash("Сигнал закрыт, действие записано в журнал");await refresh()};
 const label={critical:"Критический",urgent:"Срочный",observation:"Наблюдение",attention:"Требует внимания"};
 return <div className="backdrop"><div className="modal attention-modal"><button className="close" onClick={close}><X/></button><span className="kicker">Центр внимания</span><h2>Активные сигналы</h2><p>Красные сигналы требуют первоочередной оценки. Система не ставит диагноз и не изменяет лечение самостоятельно.</p>{alerts.length?<div className="attention-list">{alerts.map(item=><article key={item.id} className={`${item.severity||"attention"} ${item.status==="acknowledged"?"acknowledged":""}`}><span><AlertTriangle/></span><div><div className="alert-meta"><small>{item.patient_name}</small><b>{label[item.severity]||label.attention}</b>{item.status==="acknowledged"&&<b className="in-work">Принят в работу</b>}</div><strong>{item.title}</strong><p>{item.description}</p>{item.recommendation&&<em>{item.recommendation}</em>}{item.rule_codes?.length>0&&<code>{item.ruleset_version}: {item.rule_codes.join(", ")}</code>}<time>{new Date(item.created_at).toLocaleString("ru-RU")}</time><label className="alert-resolution">Результат действий<textarea value={notes[item.id]||""} onChange={e=>setNotes({...notes,[item.id]:e.target.value})} placeholder="Например: связался с пациентом, проведена оценка безопасности"/></label>{errors[item.id]&&<i className="alert-error">{errors[item.id]}</i>}</div><section><button className="outline" onClick={()=>openPatient(item.patient_id)}>Карточка пациента</button>{item.status==="new"&&<button className="outline acknowledge" onClick={()=>acknowledge(item.id)}>Принять в работу</button>}<button className="primary" onClick={()=>resolve(item.id)}>Закрыть сигнал</button></section></article>)}</div>:<div className="attention-empty"><Check/><strong>Активных сигналов нет</strong><p>Все события уже обработаны.</p></div>}</div></div>}

function PatientsLegacy({token,patients,initialPatientId,goChat,addAppointment,refresh,flash}){
 const[selected,setSelected]=useState(initialPatientId||null);const[prescribe,setPrescribe]=useState(null);const[diagnosisPatient,setDiagnosisPatient]=useState(null);
 useEffect(()=>{if(initialPatientId)setSelected(initialPatientId)},[initialPatientId]);
 return <><Title kicker="Моя практика" title="Пациенты" text="В карточке доступны состояние, заключения врачей, побочные эффекты и назначения."/>{patients.length?<div className="patient-cards">{patients.map(p=><article className="panel patient-full" key={p.patient_id}><div className="patient-line"><span>{initials(p.full_name)}</span><div><h2>{p.full_name}</h2><p><strong>Диагнозы:</strong> {p.diagnoses?.length?p.diagnoses.map(item=>item.name).join(", "):"пока не установлены"}</p></div><button className="outline" onClick={()=>setSelected(selected===p.patient_id?null:p.patient_id)}>{selected===p.patient_id?"Свернуть":"Открыть карточку"}</button></div><div className="patient-facts two-facts"><span>Терапия<strong>{p.therapy}</strong></span><span>Ежедневных отметок<strong>{p.checkins.length}</strong></span></div>{selected===p.patient_id&&<div className="patient-detail"><div><span className="kicker">Актуальное состояние</span><h3>{p.latest_checkin?`Настроение ${p.latest_checkin.mood}/10 · тревога ${p.latest_checkin.anxiety}/10`:"Ежедневных отметок ещё нет"}</h3><p>{p.latest_checkin?.note||"После ежедневного обновления здесь появится комментарий пациента."}</p></div><div><span className="kicker">Последний еженедельный опрос</span><h3>{p.assessments[0]?`${p.assessments[0].scale}: ${p.assessments[0].score} — ${p.assessments[0].level}`:"Не пройден"}</h3><p>Скрининг повторяется раз в неделю, помогает оценить динамику и не является диагнозом.</p></div><div className="diagnosis-block"><div className="diagnosis-heading"><div><span className="kicker">Диагнозы и заключения</span><p>Записи видят все врачи, работающие с пациентом.</p></div><button className="outline" onClick={()=>setDiagnosisPatient(p)}><Plus/>Добавить</button></div>{p.diagnoses?.length?<div className="diagnosis-list">{p.diagnoses.map(item=><article key={item.id}><strong>{item.name}</strong>{item.note&&<p>{item.note}</p>}<small>{item.doctor_name} · {item.doctor_specialty} · {new Date(item.created_at).toLocaleString("ru-RU")}</small></article>)}</div>:<p>Подтверждённых диагнозов пока нет.</p>}</div><div className="doctor-chart-block"><span className="kicker">Динамика состояния</span>{p.checkins.length?<DoctorStateChart items={p.checkins}/>:<p>График появится после первой ежедневной отметки.</p>}</div><div className="side-effect-block"><span className="kicker">Жалобы на побочные эффекты</span>{p.side_effect_reports.length?p.side_effect_reports.map(item=><article key={item.id} className={`side-effect-report ${item.severity}`}><div><strong>{item.medicine}</strong><small>{new Date(item.created_at).toLocaleString("ru-RU")}</small></div><p>{item.text}</p><span>{item.severity==="critical"?"Критично":item.severity==="moderate"?"Заметно мешает":"Легко"}</span></article>):<p>Пациент пока не сообщал о побочных эффектах.</p>}</div><div className="prescription-block"><span className="kicker">Назначения и приверженность</span>{p.prescriptions.length?p.prescriptions.map(item=><article className={`adherence-row ${item.adherence_level||"none"}`} key={item.id}><p><strong>{item.name}</strong> — {item.dose}, {item.frequency}</p><small>{item.taken_today?"Приём отмечен сегодня":item.missed_days>0?`Нет отметки ${item.missed_days} дн.`:"Ожидается первая отметка"}</small></article>):<p>Активных назначений пока нет.</p>}</div></div>}<div className="patient-actions"><button className="primary" onClick={()=>setDiagnosisPatient(p)}><Plus/>Поставить диагноз</button><button className="primary" onClick={()=>addAppointment(p)}><CalendarDays/>Назначить приём</button><button className="primary" onClick={()=>setPrescribe(p)}><Pill/>Назначить препарат</button><button className="wide" onClick={goChat}><MessageCircle/>Открыть чат</button></div></article>)}</div>:<Empty icon={UsersRound} title="Список пуст" text="Пациент появится после того, как самостоятельно запишется к вам."/>}{diagnosisPatient&&<DiagnosisModal token={token} patient={diagnosisPatient} close={()=>setDiagnosisPatient(null)} done={()=>{setDiagnosisPatient(null);flash("Диагнозы добавлены в карточку");refresh()}}/>}{prescribe&&<PrescriptionModal token={token} patient={prescribe} close={()=>setPrescribe(null)} done={()=>{setPrescribe(null);flash("Назначение сохранено");refresh()}}/>}</>
}

function Patients({token,patients,initialPatientId,goChat,addAppointment,refresh,flash}){
 const[selected,setSelected]=useState(initialPatientId||null);const[prescribe,setPrescribe]=useState(null);const[diagnosis,setDiagnosis]=useState(null);const[assign,setAssign]=useState(null);const[clinical,setClinical]=useState(null);const[response,setResponse]=useState(null);
 useEffect(()=>{if(initialPatientId)setSelected(initialPatientId)},[initialPatientId]);
 const completed=(patient,type)=>patient[type]||[];
 return <><Title kicker="Моя практика" title="Пациенты и анамнез" text="Ежедневные отметки, назначения и measurement-based care собраны в одной карточке."/>{patients.length?<div className="patient-cards">{patients.map(patient=><article className="panel patient-full" key={patient.patient_id}><div className="patient-line"><span>{initials(patient.full_name)}</span><div><h2>{patient.full_name}</h2><p><strong>Диагнозы:</strong> {patient.diagnoses?.length?patient.diagnoses.map(item=>item.name).join(", "):"пока не установлены"}</p></div><button className="outline" onClick={()=>setSelected(selected===patient.patient_id?null:patient.patient_id)}>{selected===patient.patient_id?"Свернуть":"Открыть карточку"}</button></div><div className="patient-facts two-facts"><span>Терапия<strong>{patient.therapy}</strong></span><span>Самоотчётов<strong>{completed(patient,"questionnaire_responses").length}</strong></span></div>{selected===patient.patient_id&&<div className="patient-detail"><section><span className="kicker">Актуальное состояние</span><h3>{patient.latest_checkin?`Настроение ${patient.latest_checkin.mood}/10 · тревога ${patient.latest_checkin.anxiety}/10`:"Ежедневных отметок ещё нет"}</h3><p>{patient.latest_checkin?.note||"Комментарий пациента пока отсутствует."}</p></section><div className="doctor-chart-block"><span className="kicker">Динамика состояния</span>{patient.checkins.length?<DoctorStateChart items={patient.checkins}/>:<p>График появится после первой отметки.</p>}</div><section className="mbc-section"><div className="mbc-head"><div><span className="kicker">Анамнез · опросники пациента</span><h3>Самоотчёты и динамика баллов</h3></div><button className="outline" onClick={()=>setAssign(patient)}><Plus/>Назначить опросник</button></div>{completed(patient,"questionnaire_responses").length?<div className="assessment-history">{completed(patient,"questionnaire_responses").map(item=><button onClick={()=>setResponse(item)} key={item.id}><div><strong>{item.title}</strong><small>{new Date(item.created_at).toLocaleDateString("ru-RU")} · {item.level}</small></div><b>{item.score}/{item.max_score}</b><ChevronRight/></button>)}</div>:<p>Назначенные опросники ещё не заполнены.</p>}</section><section className="mbc-section clinician"><div className="mbc-head"><div><span className="kicker">Анамнез · оценка врачом</span><h3>Клинические шкалы</h3></div><button className="outline" onClick={()=>setClinical(patient)}><Plus/>Заполнить шкалу</button></div>{completed(patient,"clinical_assessments").length?<div className="assessment-history">{completed(patient,"clinical_assessments").map(item=><button onClick={()=>setResponse(item)} key={item.id}><div><strong>{item.title}</strong><small>{new Date(item.created_at).toLocaleDateString("ru-RU")} · {item.doctor_name}</small></div><b>{item.score}/{item.max_score}</b><ChevronRight/></button>)}</div>:<p>Оценок врача пока нет.</p>}</section><div className="diagnosis-block"><div className="diagnosis-heading"><div><span className="kicker">Диагнозы и заключения</span><p>Записи доступны врачам, работающим с пациентом.</p></div><button className="outline" onClick={()=>setDiagnosis(patient)}><Plus/>Добавить</button></div>{patient.diagnoses?.map(item=><article key={item.id}><strong>{item.name}</strong><p>{item.note}</p><small>{item.doctor_name} · {new Date(item.created_at).toLocaleString("ru-RU")}</small></article>)}</div><div className="side-effect-block"><span className="kicker">Побочные эффекты</span>{patient.side_effect_reports.length?patient.side_effect_reports.map(item=><article key={item.id} className={`side-effect-report ${item.severity}`}><strong>{item.medicine}</strong><p>{item.text}</p></article>):<p>Жалоб нет.</p>}</div><div className="prescription-block"><span className="kicker">Назначения и приверженность</span>{patient.prescriptions.length?patient.prescriptions.map(item=><article className={`adherence-row ${item.adherence_level||"none"}`} key={item.id}><p><strong>{item.name}</strong> — {item.dose}, {item.frequency}</p><small>{item.schedule_times?.length?`Напоминания: ${item.schedule_times.join(", ")} · `:""}{item.taken_today?"приём отмечен сегодня":item.missed_days>0?`нет отметки ${item.missed_days} дн.`:"ожидается первая отметка"}</small></article>):<p>Назначений нет.</p>}</div></div>}<div className="patient-actions"><button className="primary" onClick={()=>setDiagnosis(patient)}><Plus/>Диагноз</button><button className="primary" onClick={()=>addAppointment(patient)}><CalendarDays/>Приём</button><button className="primary" onClick={()=>setPrescribe(patient)}><Pill/>Препарат</button><button className="wide" onClick={goChat}><MessageCircle/>Чат</button></div></article>)}</div>:<Empty icon={UsersRound} title="Список пуст" text="Пациент появится после записи к врачу."/>}{diagnosis&&<DiagnosisModal token={token} patient={diagnosis} close={()=>setDiagnosis(null)} done={()=>{setDiagnosis(null);flash("Диагноз сохранён");refresh()}}/>}{prescribe&&<PrescriptionModal token={token} patient={prescribe} close={()=>setPrescribe(null)} done={()=>{setPrescribe(null);flash("Назначение сохранено");refresh()}}/>}{assign&&<AssignQuestionnaireModal token={token} patient={assign} close={()=>setAssign(null)} done={()=>{setAssign(null);flash("Опросник назначен");refresh()}}/>}{clinical&&<ClinicalScaleModal token={token} patient={clinical} close={()=>setClinical(null)} done={()=>{setClinical(null);flash("Оценка врача сохранена");refresh()}}/>}{response&&<AssessmentDetail item={response} close={()=>setResponse(null)}/>}</>
}

function AssignQuestionnaireModalLegacy({token,patient,close,done}){const[items,setItems]=useState([]);const[code,setCode]=useState("");const[dueDate,setDueDate]=useState(new Date().toISOString().slice(0,10));const[repeat,setRepeat]=useState(1);const[error,setError]=useState("");useEffect(()=>{authFetch("/questionnaires?audience=patient",token).then(r=>r.json()).then(value=>{setItems(value);if(value[0])setCode(value[0].code)})},[token]);const submit=async()=>{const response=await authFetch(`/doctor/patients/${patient.patient_id}/questionnaire-assignments`,token,{method:"POST",body:JSON.stringify({questionnaire_code:code,due_date:dueDate,repeat_weeks:Number(repeat)})});const value=await response.json();if(!response.ok)return setError(value.error);done()};return <div className="backdrop"><div className="modal"><button className="close" onClick={close}><X/></button><span className="kicker">Measurement-based care</span><h2>Назначить опросник</h2><p>{patient.full_name} получит напоминание в назначенный день.</p><label className="field">Опросник<select value={code} onChange={e=>setCode(e.target.value)}>{items.map(item=><option value={item.code} key={item.code}>{item.title}</option>)}</select></label><label className="field">Дата первого заполнения<input type="date" min={new Date().toISOString().slice(0,10)} value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label><label className="field">Повторять<select value={repeat} onChange={e=>setRepeat(e.target.value)}><option value="1">Еженедельно</option><option value="2">Каждые 2 недели</option><option value="4">Каждые 4 недели</option><option value="0">Однократно</option></select></label>{error&&<p className="form-error">{error}</p>}<button className="primary modal-submit" onClick={submit}>Назначить</button></div></div>}

function AssignQuestionnaireModal({token,patient,close,done}){
 const[items,setItems]=useState([]),[code,setCode]=useState(""),[dueDate,setDueDate]=useState(new Date().toISOString().slice(0,10)),[repeat,setRepeat]=useState(1),[totalRuns,setTotalRuns]=useState(4),[error,setError]=useState("");
 useEffect(()=>{authFetch("/questionnaires?audience=patient",token).then(r=>r.json()).then(value=>{setItems(value);if(value[0])setCode(value[0].code)})},[token]);
 const changeRepeat=value=>{setRepeat(Number(value));if(Number(value)===0)setTotalRuns(1)};
 const submit=async()=>{const response=await authFetch(`/doctor/patients/${patient.patient_id}/questionnaire-assignments`,token,{method:"POST",body:JSON.stringify({questionnaire_code:code,due_date:dueDate,repeat_weeks:Number(repeat),total_runs:Number(totalRuns)})});const value=await response.json();if(!response.ok)return setError(value.error);done()};
 return <div className="backdrop"><div className="modal questionnaire-assignment-modal"><button className="close" onClick={close}><X/></button><span className="kicker">Measurement-based care</span><h2>Назначить опросник</h2><p>{patient.full_name} получит напоминание в назначенный день.</p><label className="field">Опросник<select value={code} onChange={e=>setCode(e.target.value)}>{items.map(item=><option value={item.code} key={item.code}>{item.title}</option>)}</select></label><div className="form-row"><label className="field">Дата первого заполнения<input type="date" min={new Date().toISOString().slice(0,10)} value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label><label className="field">Повторять<select value={repeat} onChange={e=>changeRepeat(e.target.value)}><option value="1">Еженедельно</option><option value="2">Каждые 2 недели</option><option value="4">Каждые 4 недели</option><option value="0">Однократно</option></select></label></div><label className="field">Сколько раз заполнить<input type="number" min="1" max="52" disabled={Number(repeat)===0} value={totalRuns} onChange={e=>setTotalRuns(Math.max(1,Number(e.target.value)))}/><small>После указанного количества заполнений опросник перестанет появляться у пациента.</small></label>{error&&<p className="form-error">{error}</p>}<button className="primary modal-submit" onClick={submit}>Назначить</button></div></div>
}

function ClinicalScaleModal({token,patient,close,done}){const[items,setItems]=useState([]);const[selected,setSelected]=useState(null);useEffect(()=>{authFetch("/questionnaires",token).then(r=>r.json()).then(setItems)},[token]);return <div className="backdrop"><div className="modal clinical-modal"><button className="close" onClick={close}><X/></button>{selected?<ScaleForm questionnaire={selected} submitPath={`/doctor/patients/${patient.patient_id}/clinical-assessments`} token={token} done={done}/>:<><span className="kicker">Оценка врачом</span><h2>Выберите клиническую шкалу</h2><div className="scale-picker">{items.map(item=><button onClick={()=>setSelected(item)} key={item.code}><strong>{item.title}</strong><small>{item.questions.length} вопросов · максимум {item.max_score}</small><ChevronRight/></button>)}</div></>}</div></div>}

function ScaleForm({questionnaire,submitPath,token,done}){const[answers,setAnswers]=useState({});const[error,setError]=useState("");const submit=async()=>{const response=await authFetch(submitPath,token,{method:"POST",body:JSON.stringify({questionnaire_code:questionnaire.code,answers})});const value=await response.json();if(!response.ok)return setError(value.error);done()};return <><span className="kicker">Клиническая шкала</span><h2>{questionnaire.title}</h2>{questionnaire.questions.map((question,index)=><section className="clinical-question" key={question.id}><strong>{index+1}. {question.prompt}</strong><select value={answers[question.id]??""} onChange={e=>setAnswers({...answers,[question.id]:Number(e.target.value)})}><option value="">Выберите оценку</option>{question.options.map(option=><option value={option.score} key={option.score}>{option.score} — {option.text||"Промежуточная оценка"}</option>)}</select></section>)}{error&&<p className="form-error">{error}</p>}<button className="primary modal-submit" disabled={Object.keys(answers).length!==questionnaire.questions.length} onClick={submit}>Сохранить оценку</button></>}

function AssessmentDetail({item,close}){return <div className="backdrop"><div className="modal assessment-detail"><button className="close" onClick={close}><X/></button><span className="kicker">Результат и ответы</span><h2>{item.title}</h2><div className="score-banner"><strong>{item.score}/{item.max_score}</strong><span>{item.level}</span></div><div className="answer-list">{item.answers.map((answer,index)=><article key={`${answer.question_id}-${index}`}><strong>{index+1}. {answer.question}</strong><p>{answer.answer} — {answer.score} балл.</p></article>)}</div></div></div>}

function DiagnosisModalLegacy({token,patient,close,done}){
 const[items,setItems]=useState([{name:"",note:""}]);const[error,setError]=useState("");const[busy,setBusy]=useState(false);
 const update=(index,key,value)=>setItems(current=>current.map((item,itemIndex)=>itemIndex===index?{...item,[key]:value}:item));
 const remove=index=>setItems(current=>current.filter((_,itemIndex)=>itemIndex!==index));
 const submit=async()=>{setError("");setBusy(true);const response=await authFetch(`/doctor/patients/${patient.patient_id}/diagnoses`,token,{method:"POST",body:JSON.stringify({diagnoses:items})});const result=await response.json();setBusy(false);if(!response.ok)return setError(result.error);done()};
 return <div className="backdrop"><div className="modal diagnosis-modal"><button className="close" onClick={close}><X/></button><span className="kicker">Клиническое заключение</span><h2>{patient.full_name}</h2><p>Можно добавить несколько диагнозов. Ваше имя, специализация и дата будут указаны автоматически.</p><div className="diagnosis-form-list">{items.map((item,index)=><section key={index}><div><strong>Диагноз {index+1}</strong>{items.length>1&&<button onClick={()=>remove(index)} title="Удалить диагноз"><X/></button>}</div><label className="field">Название диагноза<input value={item.name} maxLength="200" onChange={event=>update(index,"name",event.target.value)} placeholder="Например, генерализованное тревожное расстройство"/></label><label className="field">Комментарий для других врачей<textarea value={item.note} maxLength="1000" onChange={event=>update(index,"note",event.target.value)} placeholder="Обоснование, особенности состояния или важное уточнение"/></label></section>)}</div><button className="add-diagnosis-row" disabled={items.length>=10} onClick={()=>setItems(current=>[...current,{name:"",note:""}])}><Plus/>Добавить ещё один диагноз</button>{error&&<p className="form-error">{error}</p>}<button className="primary modal-submit" disabled={busy||items.some(item=>item.name.trim().length<2)} onClick={submit}>{busy?"Сохраняем…":"Сохранить заключение"}</button></div></div>
}

const diagnosisCatalog=["Депрессивный эпизод","Рекуррентное депрессивное расстройство","Генерализованное тревожное расстройство","Паническое расстройство","Агорафобия","Социальное тревожное расстройство","Специфическая фобия","Обсессивно-компульсивное расстройство","Посттравматическое стрессовое расстройство","Расстройство адаптации","Биполярное аффективное расстройство","Циклотимия","Дистимия","Расстройство пищевого поведения","Нервная анорексия","Нервная булимия","Расстройство сна","Соматоформное расстройство","Синдром зависимости","Синдром дефицита внимания и гиперактивности","Расстройство аутистического спектра","Расстройство личности","Диагноз уточняется"];
function DiagnosisModal({token,patient,close,done}){
 const[items,setItems]=useState([{name:"",note:""}]);const[error,setError]=useState("");const[busy,setBusy]=useState(false);
 const update=(index,key,value)=>setItems(current=>current.map((item,itemIndex)=>itemIndex===index?{...item,[key]:value}:item));
 const remove=index=>setItems(current=>current.filter((_,itemIndex)=>itemIndex!==index));
 const submit=async()=>{setError("");setBusy(true);const response=await authFetch(`/doctor/patients/${patient.patient_id}/diagnoses`,token,{method:"POST",body:JSON.stringify({diagnoses:items})});const result=await response.json();setBusy(false);if(!response.ok)return setError(result.error);done()};
 return <div className="backdrop"><div className="modal diagnosis-modal"><button className="close" onClick={close}><X/></button><span className="kicker">Клиническое заключение</span><h2>{patient.full_name}</h2><p>Начните вводить название и выберите вариант из справочника либо оставьте собственную формулировку.</p><datalist id="diagnosis-catalog">{diagnosisCatalog.map(name=><option value={name} key={name}/>)}</datalist><div className="diagnosis-form-list">{items.map((item,index)=><section key={index}><div><strong>Диагноз {index+1}</strong>{items.length>1&&<button onClick={()=>remove(index)} title="Удалить диагноз"><X/></button>}</div><label className="field">Название диагноза<input list="diagnosis-catalog" value={item.name} maxLength="200" onChange={event=>update(index,"name",event.target.value)} placeholder="Начните вводить диагноз"/></label><small>Можно выбрать подсказку или написать свой вариант.</small><label className="field">Комментарий для других врачей<textarea value={item.note} maxLength="1000" onChange={event=>update(index,"note",event.target.value)} placeholder="Обоснование, особенности состояния или важное уточнение"/></label></section>)}</div><button className="add-diagnosis-row" disabled={items.length>=10} onClick={()=>setItems(current=>[...current,{name:"",note:""}])}><Plus/>Добавить ещё один диагноз</button>{error&&<p className="form-error">{error}</p>}<button className="primary modal-submit" disabled={busy||items.some(item=>item.name.trim().length<2)} onClick={submit}>{busy?"Сохраняем…":"Сохранить заключение"}</button></div></div>
}

function DoctorStateChart({items}){const vals=items.slice(-7),w=560,h=210,p=34,x=i=>vals.length<2?w/2:p+i*(w-2*p)/(vals.length-1),y=v=>h-p-v*(h-2*p)/10,pts=k=>vals.map((v,i)=>`${x(i)},${y(v[k])}`).join(" ");return <div className="doctor-state-chart"><div className="chart-key"><span><i/>Настроение</span><span><i/>Тревога</span></div><p className="chart-note">Настроение: 0 — очень плохо, 10 — отлично. Тревога: 0 — отсутствие тревоги, 10 — сильная тревога. Оценки субъективные и не заменяют оценку специалиста.</p><svg viewBox={`0 0 ${w} ${h}`}>{[0,5,10].map(v=><g key={v}><line x1={p} y1={y(v)} x2={w-p} y2={y(v)}/><text x="7" y={y(v)+4}>{v}</text></g>)}<polyline points={pts("mood")} className="mood-path"/><polyline points={pts("anxiety")} className="anxiety-path"/>{vals.map((v,i)=><text x={x(i)} y={h-7} textAnchor="middle" key={v.id}>{new Date(v.created_at).toLocaleDateString("ru-RU",{day:"2-digit",month:"2-digit"})}</text>)}</svg></div>}

function PrescriptionModal({token,patient,close,done}){const[items,setItems]=useState([]);const[medicineId,setMedicineId]=useState("");const[customName,setCustomName]=useState("");const[customIngredient,setCustomIngredient]=useState("");const[dose,setDose]=useState("");const[frequency,setFrequency]=useState("");const[times,setTimes]=useState(["09:00"]);const[error,setError]=useState("");useEffect(()=>{fetch(`${API}/medicines`).then(r=>r.json()).then(value=>{setItems(value);if(value[0])setMedicineId(String(value[0].id))})},[]);const selected=items.find(i=>i.id===Number(medicineId));const custom=medicineId==="custom";const submit=async()=>{const r=await authFetch(`/doctor/patients/${patient.patient_id}/prescriptions`,token,{method:"POST",body:JSON.stringify({medicine_id:custom?null:Number(medicineId),custom_name:customName,custom_ingredient:customIngredient,dose,frequency,schedule_times:times.filter(Boolean)})});const result=await r.json();if(!r.ok)return setError(result.error);done()};return <div className="backdrop"><div className="modal prescription-modal"><button className="close" onClick={close}><X/></button><span className="kicker">Назначение и напоминания</span><h2>{patient.full_name}</h2><label className="field">Препарат<select value={medicineId} onChange={e=>setMedicineId(e.target.value)}>{items.map(i=><option value={i.id} key={i.id}>{i.name} · {i.ingredient}</option>)}<option value="custom">Другой препарат — ввести вручную</option></select></label>{custom?<div className="form-row"><label className="field">Название<input value={customName} onChange={e=>setCustomName(e.target.value)} placeholder="Название препарата"/></label><label className="field">Действующее вещество, если известно<input value={customIngredient} onChange={e=>setCustomIngredient(e.target.value)}/></label></div>:selected&&<div className="medicine-hint"><strong>Обычные побочные эффекты</strong><p>{selected.common_effects.join(", ")}</p><small>{selected.monitoring}</small></div>}<label className="field">Дозировка<input value={dose} onChange={e=>setDose(e.target.value)} placeholder={selected?.dose_range||"Например, 10 мг"}/></label><label className="field">Как принимать<input value={frequency} onChange={e=>setFrequency(e.target.value)} placeholder="Например, 2 раза в день после еды"/></label><section className="reminder-times"><strong>Время напоминаний</strong>{times.map((time,index)=><div key={index}><input type="time" value={time} onChange={e=>setTimes(times.map((item,i)=>i===index?e.target.value:item))}/>{times.length>1&&<button onClick={()=>setTimes(times.filter((_,i)=>i!==index))}><X/></button>}</div>)}<button className="outline" onClick={()=>setTimes([...times,"18:00"])}><Plus/>Добавить время</button></section>{error&&<p className="form-error">{error}</p>}<button className="primary modal-submit" disabled={!dose||!frequency||(custom&&!customName.trim())} onClick={submit}>Сохранить назначение</button></div></div>}

function DoctorProfile({token,doctor,refresh,flash}){const[form,setForm]=useState({...doctor});const[error,setError]=useState("");const weekdays=[[1,"Пн"],[2,"Вт"],[3,"Ср"],[4,"Чт"],[5,"Пт"],[6,"Сб"],[7,"Вс"]];const selectedDays=String(form.work_days||"").split(",");const toggleDay=value=>setForm({...form,work_days:selectedDays.includes(String(value))?selectedDays.filter(item=>item!==String(value)).join(","):[...selectedDays,String(value)].filter(Boolean).join(",")});const save=async e=>{e.preventDefault();const r=await authFetch("/doctor/profile",token,{method:"PATCH",body:JSON.stringify(form)});const result=await r.json();if(!r.ok)return setError(result.error);flash("Профиль и расписание обновлены");refresh()};return <><Title kicker="Личный кабинет" title="Мой профиль" text="Укажите рабочие дни и часы — из них автоматически формируются доступные пациентам слоты."/><form className="panel profile-form" onSubmit={save}><div className="form-row"><label>ФИО<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Специализация<input value={form.specialty} onChange={e=>setForm({...form,specialty:e.target.value})}/></label></div><div className="form-row"><label>Стаж, лет<input type="number" min="0" value={form.experience} onChange={e=>setForm({...form,experience:Number(e.target.value)})}/></label><label>Стоимость приёма, ₽<input type="number" min="2500" value={form.price} onChange={e=>setForm({...form,price:Number(e.target.value)})}/></label></div><label>Клиника<input value={form.clinic} onChange={e=>setForm({...form,clinic:e.target.value})}/></label><section className="work-schedule"><strong>Рабочие дни</strong><div>{weekdays.map(([value,label])=><button type="button" className={selectedDays.includes(String(value))?"selected":""} onClick={()=>toggleDay(value)} key={value}>{label}</button>)}</div><div className="form-row"><label>Начало работы<input type="time" value={form.work_start||"09:00"} onChange={e=>setForm({...form,work_start:e.target.value})}/></label><label>Окончание работы<input type="time" value={form.work_end||"18:00"} onChange={e=>setForm({...form,work_end:e.target.value})}/></label><label>Длительность приёма<input type="number" min="15" step="15" value={form.slot_minutes||60} onChange={e=>setForm({...form,slot_minutes:Number(e.target.value)})}/></label></div></section><label>О себе<textarea rows="5" value={form.about} onChange={e=>setForm({...form,about:e.target.value})} placeholder="Подход, образование, направления работы"/></label>{error&&<p className="form-error">{error}</p>}<button className="primary">Сохранить изменения</button></form>{doctor.is_chief&&<ChiefPanel token={token} flash={flash}/>}</>}

function ChiefPanel({token,flash}){const[data,setData]=useState(null);const[error,setError]=useState("");const load=()=>authFetch("/chief/dashboard",token).then(async response=>{const value=await response.json();if(!response.ok)throw Error(value.error);setData(value)}).catch(value=>setError(value.message));useEffect(load,[token]);const onCall=async id=>{const response=await authFetch(`/chief/on-call/${id}`,token,{method:"PUT"});const value=await response.json();if(!response.ok)return setError(value.error);flash(`${value.doctor_name} назначен дежурным`);load()};const deactivate=async doctor=>{if(!confirm(`Отключить учётную запись врача ${doctor.name}? Медицинские записи сохранятся.`))return;const response=await authFetch(`/chief/doctors/${doctor.id}`,token,{method:"DELETE"});const value=await response.json();if(!response.ok)return setError(value.error);flash("Врач отключён, история сохранена");load()};if(!data)return <section className="panel chief-panel"><h2>Управление клиникой</h2><p>{error||"Загружаем данные…"}</p></section>;return <section className="panel chief-panel"><span className="kicker">Функции главного врача</span><h2>Управление клиникой</h2><div className="chief-metrics"><span>Активных врачей<strong>{data.metrics.doctors}</strong></span><span>Пациентов<strong>{data.metrics.patients}</strong></span><span>Дежурный<strong>{data.metrics.on_call||"Не назначен"}</strong></span></div><h3>Врачи и дежурства</h3><div className="chief-doctors">{data.doctors.map(doctor=><article className={!doctor.active?"inactive":""} key={doctor.id}><div><strong>{doctor.name}</strong><small>{doctor.specialty} · {doctor.email}{doctor.is_chief?" · главный врач":""}</small></div><span>{doctor.active?doctor.is_on_call?"Сейчас дежурит":"Активен":"Отключён"}</span>{doctor.active&&!doctor.is_on_call&&<button className="outline" onClick={()=>onCall(doctor.id)}>Назначить дежурным</button>}{doctor.active&&!doctor.is_chief&&<button className="danger-button" onClick={()=>deactivate(doctor)}>Удалить врача</button>}</article>)}</div><h3>Пациенты клиники</h3><div className="chief-patients">{data.patients.map(patient=><article key={patient.id}><strong>{patient.full_name}</strong><small>{patient.doctors.length?patient.doctors.join(", "):"Нет лечащего врача"}</small></article>)}</div><p className="chief-note">Удаление врача реализовано как безопасное отключение учётной записи: история и медицинские документы не стираются.</p></section>}

function Schedule({token,days,refresh,flash}){const times=[...new Set(days.flatMap(day=>day.slots.map(slot=>slot.time)))];const rows=`58px repeat(${Math.max(1,times.length)},76px)`;const cancel=async id=>{const r=await authFetch(`/appointments/${id}/cancel`,token,{method:"POST"});if(r.ok){flash("Приём отменён, пациент получит уведомление");refresh()}};return <><Title kicker="Планирование" title="Расписание приёмов" text="Рабочие дни, часы и длительность слота задаются в профиле. Новый приём назначается из карточки пациента."/>{days.length?<div className="calendar panel" style={{gridTemplateColumns:`70px repeat(${days.length},minmax(150px,1fr))`}}><div className="calendar-hours" style={{gridTemplateRows:rows}}><span/>{times.map(time=><span key={time}>{time}</span>)}</div>{days.map(day=><div className="day" style={{gridTemplateRows:rows}} key={day.date}><div><strong>{new Intl.DateTimeFormat("ru-RU",{weekday:"short"}).format(new Date(day.date))}</strong><span>{formatDate(day.date)}</span></div>{times.map(time=>{const slot=day.slots.find(item=>item.time===time);return <div key={time} className={`schedule-cell ${slot&&!slot.available?"patient-slot":""}`}>{!slot?<span>Не работает</span>:slot.available?<span>Свободно</span>:<><strong>{slot.patient_name||"Занято"}</strong><small>{slot.status==="pending_patient"?"Ждёт подтверждения":slot.time}</small><button onClick={()=>cancel(slot.appointment_id)}>Отменить</button></>}</div>})}</div>)}</div>:<Empty icon={CalendarDays} title="Нет рабочих дней" text="Укажите график работы в профиле врача."/>}</>}

function AppointmentModal({token,doctor,patient,schedule,close,done}){const[dateValue,setDate]=useState(schedule[0]?.date||"");const[time,setTime]=useState("");const[reason,setReason]=useState("Консультация");const[error,setError]=useState("");const day=schedule.find(i=>i.date===dateValue);const submit=async()=>{const r=await authFetch("/appointments",token,{method:"POST",body:JSON.stringify({doctor_id:doctor.id,patient_id:patient.patient_id,date:dateValue,time,reason,format:"Онлайн"})});const result=await r.json();if(!r.ok)return setError(result.error);done()};return <div className="backdrop"><div className="modal"><button className="close" onClick={close}><X/></button><span className="kicker">Новый приём</span><h2>{patient.full_name}</h2><p>Пациент получит предложение и сможет подтвердить или отклонить приём.</p><label className="field">Дата<select value={dateValue} onChange={e=>{setDate(e.target.value);setTime("")}}>{schedule.map(i=><option value={i.date} key={i.date}>{formatDate(i.date)}</option>)}</select></label><div className="slot-pick">{day?.slots.map(slot=><button disabled={!slot.available} className={time===slot.time?"selected":""} onClick={()=>setTime(slot.time)} key={slot.time}>{slot.time}{!slot.available&&<small>занято</small>}</button>)}</div><label className="field">Причина<input value={reason} onChange={e=>setReason(e.target.value)}/></label>{error&&<p className="form-error">{error}</p>}<button className="primary modal-submit" disabled={!time} onClick={submit}>Отправить пациенту</button></div></div>}

function Chat({token,patients,close}){
 const[selected,setSelected]=useState(patients[0]?.patient_id||null);const[messages,setMessages]=useState([]);const[body,setBody]=useState("");const[,setSeenVersion]=useState(0);
 const seenKey=id=>`doctorChatSeen:${id}`;
 const latestIncoming=items=>(items||[]).filter(item=>item.sender==="patient").reduce((latest,item)=>Math.max(latest,Number(item.id)||0),0);
 const markSeen=(id,items)=>{const latest=latestIncoming(items),seen=Number(localStorage.getItem(seenKey(id))||0);if(latest>seen){localStorage.setItem(seenKey(id),String(latest));setSeenVersion(value=>value+1)}};
 const load=async id=>{if(!id)return setMessages([]);const r=await authFetch(`/chat/${id}`,token);const value=await r.json();if(Array.isArray(value)){setMessages(value);markSeen(id,value)}};
 useEffect(()=>{if(!selected&&patients[0])setSelected(patients[0].patient_id)},[patients,selected]);
 useEffect(()=>{load(selected);if(!selected)return;const timer=setInterval(()=>{if(document.visibilityState==="visible")load(selected)},2000);return()=>clearInterval(timer)},[selected,token]);
 const choose=patient=>{setSelected(patient.patient_id);markSeen(patient.patient_id,patient.messages)};
 const unread=patient=>latestIncoming(patient.messages)>Number(localStorage.getItem(seenKey(patient.patient_id))||0);
 const send=async()=>{if(!body.trim())return;await authFetch(`/chat/${selected}`,token,{method:"POST",body:JSON.stringify({body})});setBody("");load(selected)};
 return <><div className="chat-page-title"><Title kicker="Защищённая переписка" title="Чат с пациентом" text="Новые сообщения появляются автоматически — обновлять страницу не нужно."/><button className="chat-close" onClick={close} title="Закрыть чат"><X/>Закрыть</button></div>{!patients.length?<Empty icon={MessageCircle} title="Чатов пока нет" text="Чат появится после регистрации первого пациента."/>:<div className="chat-layout panel"><div className="chat-list">{patients.map(p=>{const hasUnread=unread(p);return <button className={`${selected===p.patient_id?"active":""} ${hasUnread?"unread":""}`} onClick={()=>choose(p)} key={p.patient_id}><span>{initials(p.full_name)}</span><div><strong>{p.full_name}</strong><small>{hasUnread?"Новое сообщение":p.messages.length?"Есть сообщения":"Начать диалог"}</small></div>{hasUnread&&<i className="chat-unread-dot"/>}</button>})}</div><div className="chat-window"><div className="chat-messages">{messages.length?messages.map(m=><div className={`bubble ${m.sender}`} key={m.id}><p>{m.body}</p><small>{new Date(m.created_at).toLocaleString("ru-RU")}</small></div>):<div className="chat-empty">Напишите первое сообщение пациенту</div>}</div><div className="composer"><input value={body} onChange={e=>setBody(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()} placeholder="Сообщение пациенту…"/><button onClick={send}><Send/></button></div></div></div>}</>
}

function Medicines(){const[items,setItems]=useState([]);const[selected,setSelected]=useState(null);useEffect(()=>{fetch(`${API}/medicines`).then(r=>r.json()).then(setItems)},[]);return <><Title kicker="Справочник" title="Препараты" text="Нажмите на препарат, чтобы открыть полную карточку. Демонстрационная база не заменяет официальную инструкцию."/><div className="medicine-list">{items.map(i=><button className="med-card" onClick={()=>setSelected(i)} key={i.id}><div className="med-icon"><Pill/></div><div><span>{i.drug_class}</span><h2>{i.name}</h2><p>{i.ingredient} · {i.dose_range}</p><div>{i.common_effects.slice(0,3).map(x=><small key={x}>{x}</small>)}</div></div><ChevronRight/></button>)}</div>{selected&&<MedicineDetails medicine={selected} close={()=>setSelected(null)}/>}</>}

function MedicineDetails({medicine,close}){return <div className="backdrop"><div className="modal medicine-details"><button className="close" onClick={close}><X/></button><div className="medicine-title"><span><Pill/></span><div><small>{medicine.drug_class}</small><h2>{medicine.name}</h2><p>{medicine.ingredient}</p></div></div><dl><div><dt>Минимальный возраст</dt><dd>{medicine.minimum_age}</dd></div><div><dt>Диапазон доз</dt><dd>{medicine.dose_range}</dd></div><div><dt>Ожидаемый эффект</dt><dd>{medicine.effect_window}</dd></div><div><dt>Мониторинг</dt><dd>{medicine.monitoring}</dd></div></dl><section className="effect-section contraindications"><strong>Противопоказания и важные ограничения</strong><div>{medicine.contraindications.map(item=><span key={item}>{item}</span>)}</div></section><section className="effect-section"><strong>Частые побочные эффекты</strong><div>{medicine.common_effects.map(item=><span key={item}>{item}</span>)}</div></section><section className="urgent-effects"><AlertTriangle/><div><strong>Побочные эффекты сильной тяжести</strong><p>{medicine.urgent_effects.join(", ")}</p></div></section><p className="medicine-disclaimer">Карточка предназначена для прототипа. Возрастные ограничения и противопоказания необходимо сверять с официальной инструкцией конкретной лекарственной формы. Решение о назначении, дозировке и отмене принимает врач.</p></div></div>}

createRoot(document.getElementById("root")).render(<App/>);
